always @(*) begin
	case (sel)
		3'd0: out = data0;
		3'd1: out = data1;
		3'd2: out = data2;
		3'd3: out = data3;
		3'd4: out = data4;
		3'd5: out = data5;
		default: out = 4'd0;
	endcase
end

endmodule"}
